using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---

// Web defaults include the default reflection-based resolver,
// so GetTypeInfo<T> will resolve any serialisable type.
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = webOptions.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialised: {json}");

Person? roundTripped = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Deserialised: {roundTripped}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// An options instance whose resolver only knows about int (not Person).
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};
// Freeze so the resolver is locked in.
limited.MakeReadOnly();

// Probing for int – should succeed
if (limited.TryGetTypeInfo<int>(out JsonTypeInfo<int>? intInfo))
    Console.WriteLine($"\nTryGetTypeInfo<int> succeeded → Type = {intInfo!.Type.Name}");
else
    Console.WriteLine("\nTryGetTypeInfo<int> failed");

// Now use a resolver that resolves *nothing* to show the "not available" path.
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};
empty.MakeReadOnly();

if (empty.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? missing))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded → {missing!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> → not available (no exception thrown)");

// ----- types -----

public record Person(string Name, int Age);

/// <summary>A resolver that never resolves any type.</summary>
file class EmptyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

